(function () {
'use strict';
var TITLE_SELECTOR = '[title]:not(link):not(meta):not(script):not(style):not(template)';
var tipEl = null;
var current = null;
var hideTimer = null;
function ensureTip() {
if (tipEl) return tipEl;
tipEl = document.createElement('div');
tipEl.id = 'moe-tooltip';
tipEl.setAttribute('role', 'tooltip');
tipEl.setAttribute('aria-hidden', 'true');
tipEl.hidden = true;
document.body.appendChild(tipEl);
return tipEl;
}
function promoteTitle(el) {
if (el.__moeTitlePromoted) return;
var tag = el.tagName;
if (tag === 'LINK' || tag === 'META' || tag === 'SCRIPT' ||
tag === 'STYLE' || tag === 'TEMPLATE' || tag === 'TITLE') {
el.__moeTitlePromoted = true;
return;
}
var t = el.getAttribute('title');
if (t && !el.getAttribute('data-tip')) {
el.setAttribute('data-tip', t);
el.setAttribute('data-native-title', t);
el.removeAttribute('title');
if (!el.getAttribute('data-tip-pos') && el.classList &&
(el.classList.contains('stat-item') ||
el.classList.contains('corner-badge') ||
el.classList.contains('arch-badge'))) {
el.setAttribute('data-tip-pos', 'top');
}
}
el.__moeTitlePromoted = true;
}
function position(target) {
var rect = target.getBoundingClientRect();
var text = target.getAttribute('data-tip') || '';
tipEl.textContent = text;
tipEl.hidden = false;
tipEl.setAttribute('aria-hidden', 'false');
var tw = tipEl.offsetWidth;
var th = tipEl.offsetHeight;
var gap = 10;
var vw = window.innerWidth;
var vh = window.innerHeight;
tipEl.classList.remove('tip-left', 'tip-top', 'tip-bottom');
var want = target.getAttribute('data-tip-pos') || 'right';
var roomRight = (vw - rect.right) >= tw + gap;
var roomLeft = rect.left >= tw + gap;
var side = want;
if (want === 'right' && !roomRight) side = roomLeft ? 'left' : 'right';
if (want === 'left' && !roomLeft) side = roomRight ? 'right' : 'left';
var x, y;
if (side === 'right') {
x = rect.right + gap;
y = rect.top + rect.height / 2 - th / 2;
} else if (side === 'left') {
x = rect.left - gap - tw;
y = rect.top + rect.height / 2 - th / 2;
tipEl.classList.add('tip-left');
} else if (side === 'top') {
x = rect.left + rect.width / 2 - tw / 2;
y = rect.top - gap - th;
tipEl.classList.add('tip-top');
} else {
x = rect.left + rect.width / 2 - tw / 2;
y = rect.bottom + gap;
tipEl.classList.add('tip-bottom');
}
x = Math.max(8, Math.min(x, vw - tw - 8));
y = Math.max(8, Math.min(y, vh - th - 8));
tipEl.style.left = x + 'px';
tipEl.style.top = y + 'px';
}
function show(target) {
if (!target || !target.getAttribute) return;
if (target.closest && target.closest('[data-tip-local]')) return;
var text = target.getAttribute('data-tip');
if (!text) return;
if (hideTimer) { clearTimeout(hideTimer); hideTimer = null; }
ensureTip();
current = target;
position(target);
tipEl.classList.add('show');
}
function hide() {
if (!tipEl) return;
if (hideTimer) { clearTimeout(hideTimer); hideTimer = null; }
tipEl.classList.remove('show');
tipEl.setAttribute('aria-hidden', 'true');
current = null;
hideTimer = setTimeout(function () { if (tipEl) tipEl.hidden = true; }, 160);
}
function bindEvents() {
document.addEventListener('mouseover', function (e) {
var t = e.target.closest ? e.target.closest('[data-tip]') : null;
if (t && t !== current) show(t);
});
document.addEventListener('mouseout', function (e) {
if (!current) return;
var related = e.relatedTarget;
if (related && current.contains(related)) return;
if (related && related.closest && related.closest('[data-tip]') === current) return;
hide();
});
document.addEventListener('focusin', function (e) {
var t = e.target.closest ? e.target.closest('[data-tip]') : null;
if (t) show(t);
});
document.addEventListener('focusout', function () { hide(); });
document.addEventListener('click', function () { hide(); });
window.addEventListener('scroll', function () { hide(); }, true);
window.addEventListener('resize', function () { hide(); });
document.addEventListener('keydown', function (e) {
if (e.key === 'Escape') hide();
});
}
function scan(root) {
var scope = root || document;
var nodes = scope.querySelectorAll ? scope.querySelectorAll(TITLE_SELECTOR) : [];
for (var i = 0; i < nodes.length; i++) promoteTitle(nodes[i]);
}
function init() {
ensureTip();
bindEvents();
scan(document);
if (window.MutationObserver) {
var mo = new MutationObserver(function (mutations) {
mutations.forEach(function (m) {
m.addedNodes.forEach(function (node) {
if (node.nodeType === 1) scan(node);
});
});
});
mo.observe(document.body, { childList: true, subtree: true });
}
if (/[?&]tip_demo=1/.test(location.search)) {
setInterval(function () {
var nodes = document.querySelectorAll('.article-card-stats .stat-item');
var fav = null, nearest = null, bd = 1e9, cy = innerHeight / 2;
for (var i = 0; i < nodes.length; i++) {
var r = nodes[i].getBoundingClientRect();
if (r.bottom <= 0 || r.top >= innerHeight) continue;
var d = Math.abs(r.top + r.height / 2 - cy);
if (d < bd) { bd = d; nearest = nodes[i]; }
if ((nodes[i].getAttribute('data-tip') || '').indexOf('收藏') !== -1 &&
(!fav || d < fav.d)) { fav = { el: nodes[i], d: d }; }
}
var pick = fav ? fav.el : nearest;
if (pick && pick !== current) show(pick);
}, 500);
}
}
if (document.readyState === 'loading') {
document.addEventListener('DOMContentLoaded', init);
} else {
init();
}
})();
(function () {
'use strict';
var STORAGE_KEY = 'mouse_effect_enabled';
var enabled = (function () {
try {
return localStorage.getItem(STORAGE_KEY) !== 'false';
} catch (e) {
return true;
}
})();
var MAX_PARTICLES = 60;
var GRAVITY = 0.08;
var PARTICLE_SIZE_MIN = 6;
var PARTICLE_SIZE_MAX = 12;
var SPAWN_PER_MOVE = 2;
var canvas = null;
var ctx = null;
var mounted = false;
var eventsBound = false;
var running = false;
function ensureCanvas() {
if (canvas) return;
canvas = document.createElement('canvas');
canvas.setAttribute('aria-hidden', 'true');
ctx = canvas.getContext('2d');
canvas.style.cssText =
'position:fixed;top:0;left:0;width:100vw;height:100vh;' +
'pointer-events:none;z-index:9999;';
}
function startEffect() {
if (mounted) return;
ensureCanvas();
document.body.appendChild(canvas);
resize();
bindEvents();
running = true;
mounted = true;
loop();
}
function stopEffect() {
running = false;
particles = [];
if (canvas && canvas.parentNode) {
canvas.parentNode.removeChild(canvas);
}
mounted = false;
}
function toggleMouseEffect() {
enabled = !enabled;
try {
localStorage.setItem(STORAGE_KEY, enabled ? 'true' : 'false');
} catch (e) { }
if (enabled) {
startEffect();
} else {
stopEffect();
}
updateToggleButton();
return enabled;
}
window.toggleMouseEffect = toggleMouseEffect;
function resize() {
var dpr = Math.min(window.devicePixelRatio || 1, 2);
canvas.width = Math.floor(window.innerWidth * dpr);
canvas.height = Math.floor(window.innerHeight * dpr);
ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
}
var particles = [];
function spawn(x, y) {
var type = Math.random() < 0.5 ? 'petal' : 'star';
var size = PARTICLE_SIZE_MIN + Math.random() * (PARTICLE_SIZE_MAX - PARTICLE_SIZE_MIN);
particles.push({
x: x,
y: y,
vx: (Math.random() - 0.5) * 2,
vy: Math.random() * 0.5,
size: size,
rotation: Math.random() * Math.PI * 2,
rotationSpeed: (Math.random() - 0.5) * 0.1,
life: 1,
decay: 0.008 + Math.random() * 0.012,
type: type,
color: type === 'petal'
? 'rgba(255, 143, 177,'
: 'rgba(160, 108, 213,'
});
while (particles.length > MAX_PARTICLES) {
particles.shift();
}
}
function drawParticle(p) {
ctx.save();
ctx.translate(p.x, p.y);
ctx.rotate(p.rotation);
ctx.globalAlpha = Math.max(p.life, 0);
if (p.type === 'petal') {
ctx.fillStyle = p.color + '0.9)';
ctx.beginPath();
ctx.ellipse(0, 0, p.size, p.size * 0.55, 0, 0, Math.PI * 2);
ctx.fill();
} else {
ctx.fillStyle = p.color + '0.95)';
var r = p.size;
ctx.beginPath();
for (var i = 0; i < 8; i++) {
var angle = (Math.PI / 4) * i;
var radius = (i % 2 === 0) ? r : r * 0.4;
var px = Math.cos(angle) * radius;
var py = Math.sin(angle) * radius;
if (i === 0) ctx.moveTo(px, py);
else ctx.lineTo(px, py);
}
ctx.closePath();
ctx.fill();
}
ctx.restore();
}
function update() {
for (var i = particles.length - 1; i >= 0; i--) {
var p = particles[i];
p.vy += GRAVITY;
p.x += p.vx;
p.y += p.vy;
p.rotation += p.rotationSpeed;
p.life -= p.decay;
if (p.life <= 0 || p.y > window.innerHeight + 20) {
particles.splice(i, 1);
}
}
}
function render() {
ctx.clearRect(0, 0, window.innerWidth, window.innerHeight);
for (var i = 0; i < particles.length; i++) {
drawParticle(particles[i]);
}
}
function loop() {
if (!running) return;
if (!document.hidden) {
update();
render();
}
requestAnimationFrame(loop);
}
function bindEvents() {
if (eventsBound) return;
eventsBound = true;
window.addEventListener('resize', resize);
var lastSpawn = 0;
window.addEventListener('mousemove', function (e) {
if (!running) return;
var now = performance.now();
if (now - lastSpawn < 16) return;
lastSpawn = now;
for (var i = 0; i < SPAWN_PER_MOVE; i++) {
spawn(e.clientX + (Math.random() - 0.5) * 6,
e.clientY + (Math.random() - 0.5) * 6);
}
}, { passive: true });
window.addEventListener('touchmove', function (e) {
if (!running) return;
if (!e.touches || e.touches.length === 0) return;
var t = e.touches[0];
for (var i = 0; i < SPAWN_PER_MOVE; i++) {
spawn(t.clientX + (Math.random() - 0.5) * 6,
t.clientY + (Math.random() - 0.5) * 6);
}
}, { passive: true });
document.addEventListener('visibilitychange', function () {
if (document.hidden) {
running = false;
} else if (!running && mounted) {
running = true;
loop();
}
});
}
function updateToggleButton() {
var btn = document.getElementById('mouse-effect-toggle');
if (!btn) return;
btn.style.opacity = enabled ? '1' : '.45';
btn.title = enabled ? '切换鼠标特效（当前开启）' : '切换鼠标特效（当前关闭）';
}
function bindToggleButton() {
var btn = document.getElementById('mouse-effect-toggle');
if (!btn) return;
updateToggleButton();
btn.addEventListener('click', function () {
toggleMouseEffect();
});
}
function boot() {
if (enabled) {
startEffect();
}
bindToggleButton();
}
if (document.readyState === 'loading') {
document.addEventListener('DOMContentLoaded', boot);
} else {
boot();
}
})();
(function () {
'use strict';
var btn = document.getElementById('sakura-mode-toggle');
if (!btn) return;
var STATES = ['off', 'light', 'dense'];
var LABELS = { off: '🌺', light: '🌸', dense: '🌺' };
var TITLES = {
off: '樱花模式：关闭（点击开启淡模式）',
light: '樱花模式：淡（点击开启浓模式）',
dense: '樱花模式：浓（点击关闭）'
};
var basePetals = Array.prototype.slice.call(
document.querySelectorAll('.sakura-deco')
);
var densePetals = [];
function getState() {
var s = 'off';
try {
s = localStorage.getItem('sakura_mode') || 'off';
} catch (err) {}
return STATES.indexOf(s) >= 0 ? s : 'off';
}
function save(s) {
try { localStorage.setItem('sakura_mode', s); } catch (err) {}
}
function makePetal() {
var span = document.createElement('span');
span.className = 'sakura-deco sakura-dense';
span.style.left = (Math.random() * 96) + '%';
span.style.animationDuration = (8 + Math.random() * 6) + 's';
span.style.animationDelay = (Math.random() * 5) + 's';
span.style.transform =
'scale(' + (1.2 + Math.random() * 0.8) + ')';
document.body.appendChild(span);
return span;
}
function apply(s) {
var showBase = (s !== 'off');
basePetals.forEach(function (p) {
p.style.display = showBase ? '' : 'none';
});
if (s === 'dense') {
while (densePetals.length < 10) {
densePetals.push(makePetal());
}
densePetals.forEach(function (p) {
p.style.display = '';
});
} else {
densePetals.forEach(function (p) {
p.style.display = 'none';
});
}
btn.textContent = LABELS[s];
btn.title = TITLES[s];
}
btn.addEventListener('click', function () {
var cur = getState();
var next = STATES[(STATES.indexOf(cur) + 1) % STATES.length];
save(next);
apply(next);
});
apply(getState());
})();